```json
{"concepto": "Ciclo de trayectoria del agente (Trajectory Loop)", "enunciado": "\\text{Trajectory}_{t} \\xrightarrow{\\text{LLM}} \\text{Thought + Tool Call} \\xrightarrow{\\text{Environment}} \\text{Observation}_{t+1} \\xrightarrow{\\text{append}} \\text{Trajectory}_{t+1}", "problema": "estructurar la computación iterativa de un agente que refina decisiones mediante retroalimentación del ambiente", "limite": "requiere un ambiente ejecutable que procese llamadas a herramientas y produzca observaciones", "patron": "un bucle que concatena observaciones previas, genera una acción, obtiene retroalimentación del ambiente y extiende el historial para la siguiente iteración", "linea": 113}
{"concepto": "Métrica Pass@K (probabilidad de paso en K muestras)", "enunciado": "probabilidad de que en K muestras independientes al menos una pase los tests del problema", "problema": "evaluar si muestreo múltiple de un modelo genera al menos una solución correcta", "limite": "no equivale al desempeño en sistemas que solo permiten una salida; su validez depende del modo de uso real (una vs múltiples pruebas)", "patron": "cuando tienes oportunidad de intentar múltiples soluciones y aceptas cualquiera correcta, el éxito mejora; sin oportunidad de reintento, solo la primera salida importa", "linea": 168}
{"concepto": "Asignación de presupuesto de computación en tiempo de prueba (Test-Time Budget Allocation)", "enunciado": "decisión de continuar refinando la trayectoria actual versus descartar y resintonizar", "problema": "optimizar uso de computación limitada entre exploración profunda de un camino versus exploración de múltiples caminos", "limite": "varía con complejidad de la tarea: cambios menores pueden permitir remuestra barata, cambios multiarquivo justifican preservación de contexto", "patron": "ante un resultado parcialmente correcto pero no validado, comparar el costo de iteración local versus el costo de partida de una trayectoria nueva", "linea": 142}
{"concepto": "Espectro de flujo de control (Control Flow Spectrum)", "enunciado": "rango desde ReAct totalmente dinámico (shell + herramientas sin restricción) hasta máquina de estados explícita que limita acciones en cada paso", "problema": "balancear flexibilidad de exploración contra riesgo de deriva de trayectoria y costo incontrolado", "limite": "control muy fuerte restringe espacio de búsqueda y puede perder soluciones; control muy débil produce trayectorias largas y difíciles de auditar", "patron": "un continuo donde mayor restricción incrementa previsibilidad y auditabilidad, pero reduce capacidad de recuperación ante anomalías inesperadas", "linea": 259}
{"concepto": "Ciclo mínimo de verificación de vulnerabilidades (Security Agent Verification Loop)", "enunciado": "1) hipótesis sobre vulnerabilidad en ruta; 2) generar entrada ejecutable o script de disparo; 3) correr bajo sanitizer/debugger y recopilar evidencia; 4) fallar → revisar hipótesis y reintentar hasta reproducir o refutar", "problema": "cerrar lazo entre análisis estático y confirmación dinámica de exploitabilidad de un defecto", "limite": "requiere tooling dinámico (sanitizer, debugger, harness ejecución); vulnerabilidades requieren entrada/contexto muy específico", "patron": "cuando no puedes confiar solo en análisis local, ejecuta pruebas bajo observador dinámico, usa sus señales para iterar tu modelo de problema", "linea": 306}
{"concepto": "Verificación dinámica versus clasificación estática (Dynamic vs Static Verification)", "enunciado": "transición desde etiquetado estático de funciones (vulnerable/no vulnerable) hacia validación ejecutable con entrada que dispara comportamiento observable", "problema": "diferenciar vulnerabilidades reales de falsos positivos que parecen riesgosos pero carecen de ruta alcanzable o contexto de disparo válido", "limite": "verificación estática es barata pero imprecisa; verificación dinámica es cara pero más confiable, y la cobertura de espacios de entrada es incompleta", "patron": "si no puedes ejecutar y observar el comportamiento comprometido, tu confianza en la clasificación es limitada; la ejecución instrumentada proporciona señales de verdad de terreno", "linea": 324}
{"concepto": "Complementariedad Fuzzing-Agent (Fuzzing and Agent Complementarity)", "enunciado": "Fuzzing domina en exploración aleatoria de alto rendimiento; Agent domina en búsqueda dirigida por semántica; combinación logra cobertura amplia + profundización en ramas lógicas profundas", "problema": "explorar eficientemente espacio de entrada de programas, balanceando cobertura vs profundidad de caminos específicos", "limite": "fuzzing ciego requiere recursos masivos para rutas profundas; agentes requieren conocimiento de dominio y son caros en computación, pero escalables a semántica compleja", "patron": "generador barato y estocástico explora ampliamente; razonador caro y semántico se enfoca en rutas donde tiene confianza; combina hits aleatorios con dirección inteligente", "linea": 358}
{"concepto": "Alineación de métricas (Metric Misalignment Problem)", "enunciado": "optimizar Pass@K cuando el caso de uso productivo solo permite una salida genera sistemas de alta «diversidad simulada» pero baja calidad de primera respuesta", "problema": "evitar que la métrica de evaluación guíe a los equipos a optimizar para el benchmark incorrecto", "limite": "la desalineación solo es visible en despliegue, no durante desarrollo; es especialmente problemático cuando benchmark y caso real difieren en oportunidades de reintento", "patron": "cuando el incentivo de optimización no alinea con restricción del mundo real, el sistema se entrena para maximizar disponibilidad de respuesta correcta en el pool, no disponibilidad al primer intento", "linea": 177}
{"concepto": "Vida útil de benchmark (Benchmark Shelf Life)", "enunciado": "todos los benchmarks tienen período limitado donde mantienen valor discriminativo; inicialmente difíciles e inéditos, con el tiempo se vuelven fáciles e infiltrados en datos de entrenamiento", "problema": "evitar que equipos optimicen indefinidamente para objetivos obsoletos que ya no miden capacidad real", "limite": "es imposible predecir exactamente cuándo un benchmark pierde validez; algunos duran años, otros meses", "patron": "la efectividad de un objetivo de optimización es una función del tiempo; requiere auditoría periódica y reemplazo de benchmarks para mantener dirección de mejora significativa", "linea": 220}
{"concepto": "Dependencia de contexto en determinación de vulnerabilidad (Semantic Vulnerability Context Dependency)", "enunciado": "una función aislada no puede clasificarse como vulnerable o no vulnerable; la vulnerabilidad emergen de: rutas alcanzables, restricciones de llamador, flujo de datos intermodular, condiciones de ambiente de ejecución", "problema": "evitar falsos positivos de análisis local que ignoran restricciones globales, y falsos negativos de funciones que parecen seguras localmente pero son explotables en composición", "limite": "requerimiento de análisis interprocedural completo es computacionalmente prohibitivo para sistemas grandes; análisis parcial es inevitable", "patron": "la caracterización de peligro de un fragmento de código requiere contexto de llamada completo; sin él, la clasificación binaria es mal definida", "linea": 343}
{"concepto": "Clasificación de tipos de fallos de Agent (Failure Type Classification)", "enunciado": "fallos se clasifican en cinco categorías: retrieval (búsqueda de archivo equivocado), execution (invocación de herramienta malformada), verification (test incorrecto o verifier engañado), policy (refuerzo de hipótesis errónea), cost (limitaciones de presupuesto de token/tiempo)", "problema": "diagnosticar sistemáticamente por qué un agente fracasa para dirigir mejoras de sistema en lugar de re-parametrizar ciegamente", "limite": "algunas fallas son compuestas (retrieval malo → execution error → verificador malinterpretado); clasificación no siempre es limpia", "patron": "cuando fallos se mapean a categorías consistentes, cada categoría mapea a una dirección de mejora de sistema (retrieval → tool design, execution → ACI clarity, verification → oracle strength)", "linea": 476}
{"concepto": "Flujo de control dual: exploración versus verificación (Dual-Mode Control Flow)", "enunciado": "modo exploración: alta tasa de muestreo, múltiples rutas, permisos amplios de herramientas; modo verificación: baja tasa de muestreo, rutas constreñidas, observación puntos fijos", "problema": "balancear capacidad de descubrimiento inicial contra necesidad de reproducibilidad y auditabilidad antes de conclusión final", "limite": "cambiar modos tiene overhead; tiempos de espera de exploración pueden exceder presupuesto si no se estiman bien", "patron": "fases iniciales de búsqueda toleran divergencia por mayor cobertura; fases finales de cierre requieren determinismo para que cada paso sea explicable y replayable", "linea": 495}
{"concepto": "Jerarquía de gestión de presupuesto de computación (Budget Management Hierarchy)", "enunciado": "tres niveles anidados: (1) presupuesto por trayectoria (máx pasos y ejecuciones), (2) presupuesto por tarea (máx trayectorias y tiempo total), (3) presupuesto por batch (máx GPU/CPU horas)", "problema": "prevenir desbordamiento de costo sin sacrificar resultados; hacer explícito dónde se agota recurso", "limite": "niveles deben ser jerarquizados de forma que violación de nivel más bajo no dispare nivel superior; requiere monitoreo en tiempo real", "patron": "presupuestos anidados con escalas diferentes permiten graceful degradation: cuando capa local se agota, sistema explica por qué se detuvo, en lugar de timeout opaco", "linea": 504}
